const TURNOVER_TYPES = [
  { key: "badPass", label: "Bad Pass", about: "Pass is inaccurate, intercepted, thrown away, or a teammate can't reasonably handle it. Tells us about passing/playmaking." },
  { key: "lostHandle", label: "Lost Handle", about: "Dribble off the foot, lose control, or mishandle the ball without a defender directly causing it. Tells us about ball handling." },
  { key: "stripped", label: "Stripped", about: "A defender knocks the ball away while dribbling or attacking. Tells us about ball security under pressure." },
  { key: "driveError", label: "Drive/Finish Error", about: "Travel, offensive foul, losing the ball while gathering, or stepping out while attacking. Tells us about scoring creation." },
  { key: "decisionError", label: "Possession/Decision Error", about: "Holding the ball too long, getting trapped with no outlet, or another clear bad decision that doesn't fit the categories above. Tells us about decision-making." },
  { key: "other", label: "Other", about: "Anything genuinely outside the categories above." }
];

function turnoverTypeLabel(key) {
  const t = TURNOVER_TYPES.find(x => x.key === key);
  return t ? t.label : "No type yet";
}

const TURNOVER_TYPE_MIN_TAGGED = 5;

const SELF_INFLICTED_TURNOVER_TYPES = new Set(["badPass", "lostHandle", "decisionError", "driveError"]);

const FORCED_TURNOVER_TYPES = new Set(["stripped"]);

function computeTurnoverTypeBreakdown(playerId) {
  const counts = Object.fromEntries(TURNOVER_TYPES.map(t => [t.key, 0]));
  let tagged = 0;
  qualifyingGamesForPlayer(playerId).forEach(game => {
    game.turnoverEvents.forEach(ev => {
      if (ev.playerId !== playerId) return;
      if (ev.missEventId) return;
      if (!ev.turnoverType || counts[ev.turnoverType] === undefined) return;
      counts[ev.turnoverType]++;
      tagged++;
    });
  });
  let selfInflicted = 0, forced = 0;
  Object.entries(counts).forEach(([key, n]) => {
    if (SELF_INFLICTED_TURNOVER_TYPES.has(key)) selfInflicted += n;
    else if (FORCED_TURNOVER_TYPES.has(key)) forced += n;
  });
  return {
    counts, tagged, selfInflicted, forced,
    selfInflictedPct: tagged >= TURNOVER_TYPE_MIN_TAGGED ? pct(selfInflicted, tagged) : null,
    forcedPct: tagged >= TURNOVER_TYPE_MIN_TAGGED ? pct(forced, tagged) : null,
  };
}

const TURNOVER_TYPE_CSS_CLASS = { badPass: "tov-seg-badpass", lostHandle: "tov-seg-losthandle", decisionError: "tov-seg-decisionerror", stripped: "tov-seg-stripped" };

function computeTurnoverTypeTaggedSummary() {
  let total = 0, tagged = 0;
  state.games.filter(isQualifyingGame).forEach(game => {
    game.turnoverEvents.forEach(ev => {
      if (ev.missEventId) return;
      total++;
      if (ev.turnoverType) tagged++;
    });
  });
  return { total, tagged, pct: pct(tagged, total) };
}

function turnoverTypeTaggedSummaryText() {
  const s = computeTurnoverTypeTaggedSummary();
  return s.total === 0 ? "No live-ball turnovers logged yet." : `${s.tagged} of ${s.total} turnovers tagged (${formatPct(s.pct)}).`;
}

